function expDrawLandscape(){if(!expBiome)return;
 const frontier=expBiome==='science'?2200:4800;
 const left=Math.max(frontier,cam.x-W/(2*cam.zoom)-400),right=cam.x+W/(2*cam.zoom)+400;
 if(right>left){ctx.fillStyle=expBiome==='science'?'#424a35':'#385445';ctx.fillRect(left,cam.y-H/(2*cam.zoom)-400,right-left,H/cam.zoom+800);
  const stx=Math.floor(left/96)*96,ety=cam.y+H/(2*cam.zoom)+400;for(let x=stx;x<right;x+=96)for(let y=Math.floor((cam.y-H/(2*cam.zoom)-400)/96)*96;y<ety;y+=96){let n=(Math.abs(Math.sin(x*0.0021+y*0.0054)*53831))%1;ctx.fillStyle=n>.5?'#69825355':'#162f2655';ctx.fillRect(x+(n*39),y+43,2+(n*4),2+(n*4));}}
 for(const region of EXP.districts){if(region.id.startsWith(expBiome)&&expInView(region.center[0],region.center[1],200)){ctx.save();ctx.fillStyle='#d7f9e8a8';ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.fillText('◈ '+region.name.toUpperCase(),region.center[0],region.center[1]-560);ctx.restore();}}
 }
function expDrawRoutes(){if(!expBiome)return;for(const line of EXP.routes[expBiome]){
  if(!line.some(([x,y])=>expInView(x,y,1200)))continue;
  ctx.beginPath();ctx.moveTo(...line[0]);for(let i=1;i<line.length;i++)ctx.lineTo(...line[i]);
  ctx.strokeStyle=expBiome==='science'?'#443c32cc':'#534632b5';ctx.lineWidth=78;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();ctx.strokeStyle=expBiome==='science'?'#96917cbb':'#8c7a58ab';ctx.lineWidth=62;ctx.stroke();
 }
}
function expDrawProps(){if(!expBiome)return;for(const a of expProps){if(!expInView(a.x,a.y,400))continue;const r=img(a.file);if(!r?.ready)continue;let ow=r.img.naturalWidth,oh=r.img.naturalHeight;if(!ow||!oh)continue;const w=a.w,h=a.w*oh/ow;if(h>360)continue;ctx.drawImage(r.img,a.x-w/2,a.y-h,w,h);}
}
function expDrawCharacters(){if(!expBiome)return;
 for(const a of expNpcs){if(!expInView(a.x,a.y,300))continue;const near=Math.hypot(worldX(player.x)-a.x,worldY(player.y)-a.y)<145;const phase=(gameTime+a.seed)%11;const act=near?'interagir':phase>5.6&&phase<8.2?'andar':'idle';const frames=a.animations[act]||a.animations.idle||[],f=frames[Math.floor(gameTime*(act==='andar'?6:3)+a.seed)%frames.length];if(!f)continue;const r=img(f);if(!r?.ready)continue;
  let w=Math.min(72,r.img.naturalWidth*0.7),h=Math.min(100,r.img.naturalHeight*w/r.img.naturalWidth);
  const drift=act==='andar'?Math.sin((phase-5.6)*2)*10:0;ctx.drawImage(r.img,a.x+drift-w/2,a.y-h+4+Math.sin(gameTime*2+a.seed)*1.6,w,h);
  if(Math.hypot(worldX(player.x)-a.x,worldY(player.y)-a.y)<175){ctx.fillStyle='#0c1c27cd';ctx.fillRect(a.x-95,a.y-h-40,190,25);ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillStyle='#e5ffe3';ctx.fillText(a.name,a.x,a.y-h-22);}
 }
 for(const a of expSamples){if(a.done||!expInView(a.x,a.y,180))continue;ctx.save();ctx.translate(a.x,a.y);ctx.shadowBlur=25;ctx.shadowColor=a.color;ctx.fillStyle=a.color;let bob=Math.sin(gameTime*4)*5;ctx.beginPath();ctx.moveTo(0,-42+bob);ctx.lineTo(19,-19+bob);ctx.lineTo(0,4+bob);ctx.lineTo(-19,-19+bob);ctx.closePath();ctx.fill();ctx.restore();}
 if(expPortal&&expInView(expPortal.x,expPortal.y,250)){let a=expPortal;ctx.save();ctx.translate(a.x,a.y);ctx.strokeStyle='#a38afd';ctx.shadowColor='#a38afd';ctx.shadowBlur=19;ctx.lineWidth=8;ctx.beginPath();ctx.ellipse(0,-55,48,66,0,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#e8dfff';ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillText(a.label,0,-134);ctx.restore();}
 }
function expDrawPrompt(){const near=expNearby(170);if(near){ctx.save();ctx.fillStyle='#0c1828ef';ctx.strokeStyle='#9be8db';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(W/2-170,H-148,340,36,9);ctx.fill();ctx.stroke();ctx.fillStyle='#e5ffec';ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.fillText('F  •  '+(near.kind==='npc'?'CONVERSAR':near.kind==='sample'?'COLETAR':'ATRAVESSAR'),W/2,H-125);ctx.restore();}
}

