function levelPortal(){expPortal=activeLevel?.portal&&campaign.maeraSpoken?{id:'portal-'+current,x:activeLevel.portal[0],y:activeLevel.portal[1],sprite:activeLevel.world==='science'?'v7_portal_aion':'v7_portal_vitralia',scale:1,label:activeLevel.world==='science'?'PORTAL VITRÁLIA':'PORTAL AION'}:null;}
function levelFloorFiles(margin=0){if(cam.zoom<.45&&activeLevel.floor?.overview)return [];const size=activeLevel.floor?.size||512,box={x:cam.x-W/(2*cam.zoom)-margin,y:cam.y-H/(2*cam.zoom)-margin,w:W/cam.zoom+margin*2,h:H/cam.zoom+margin*2},out=[];for(let y=Math.floor(box.y/size);y<=Math.floor((box.y+box.h)/size);y++)for(let x=Math.floor(box.x/size);x<=Math.floor((box.x+box.w)/size);x++){const file=activeLevel.floor?.files?.[x+','+y];if(file)out.push({file,x:x*size,y:y*size});}return out;}
function levelPreload(){const wanted=new Set(levelFloorFiles(activeLevel.floor?.size||512).map(q=>q.file));if(cam.zoom<.45&&activeLevel.floor?.overview)wanted.add(activeLevel.floor.overview);for(const o of levelQuery(levelObjects,{x:player.x-900,y:player.y-650,w:1800,h:1300}))if(levelManifest(o.sprite)?.file)wanted.add(levelManifest(o.sprite).file);for(const n of [...expNpcs,...enemies,...pickups,player])if(Math.hypot(n.x-player.x,n.y-player.y)<1100&&levelManifest(n.sprite)?.file)wanted.add(levelManifest(n.sprite).file);if(player.sprite==='scientist'){for(const id of ['idle','walkl','walkr','walkf'])for(const frame of DATA.intro.animations.SpriteFrames_fpb5v[id]?.frames||[])wanted.add(frame.file);}return [...wanted];}
function levelNearby(limit=110){if(!player)return null;const candidates=[];for(const o of activeLevel.objects||[])if(o.expScan&&!o.hidden)candidates.push({x:o.x,y:o.y,kind:'experiment',name:o.name,token:o.expScan});for(const o of activeLevel.objects||[])if(o.connection&&!o.hidden)candidates.push({x:o.x,y:o.y,kind:'connection',name:o.name||'Atravessar',connection:o.connection});for(const n of expNpcs)if(!n.hidden&&!n.companion)candidates.push({...n,kind:'npc'});for(const s of expSamples)if(!s.done&&(s.id.startsWith('sample')||campaign.maeraSpoken))candidates.push({...s,kind:'sample'});if(expPortal)candidates.push({...expPortal,kind:'portal'});if(current==='world1'&&activeLevel.labDoor)candidates.push({x:activeLevel.labDoor[0],y:activeLevel.labDoor[1],kind:'lab',name:'Laboratório AION'});if(activeLevel.exit)candidates.push({x:activeLevel.exit[0],y:activeLevel.exit[1],kind:'exit',name:'Voltar ao exterior'});for(const o of levelQuery(levelObjects,{x:player.x-limit*2,y:player.y-limit*2,w:limit*4,h:limit*4}))if(o.enter){const point=o.door||[o.x,o.y];candidates.push({x:point[0],y:point[1],kind:'door',name:o.name||'Entrar',enter:o.enter});}for(const o of levelQuery(levelObjects,{x:player.x-limit*2,y:player.y-limit*2,w:limit*4,h:limit*4}))if(o.harvest&&!(campaign.fieldItems||[]).includes('harvest:'+o.id))candidates.push({x:o.x,y:o.y+20,kind:'harvest',name:'Colher '+o.harvest.name,id:o.id,harvest:o.harvest});else if(o.interact?.type==='rune')candidates.push({x:o.x,y:o.y+30,kind:'rune',name:o.interact.label,interact:o.interact});for(const p of pickups)if(!p.done)candidates.push({...p,kind:p.kind==='crystal'?'crystal':'field',name:p.name||'Cristal de Limiar'});return candidates.filter(a=>Math.hypot(player.x-a.x,player.y-a.y)<limit).sort((a,b)=>Math.hypot(player.x-a.x,player.y-a.y)-Math.hypot(player.x-b.x,player.y-b.y))[0]||null;}
function levelRune(target){if(campaign.limiarPuzzle){popup('O LIMIAR JÁ ESTÁ ESTABILIZADO');return;}campaign.runeSequence=campaign.runeSequence||[];const rune=target.interact;if(rune.order!==campaign.runeSequence.length){campaign.runeSequence=[];popup('RESSONÂNCIA INSTÁVEL · RECOMECE PELO COBRE');saveCampaign();return;}campaign.runeSequence.push(rune.id);const count=(activeLevel.objects||[]).filter(o=>o.interact?.type==='rune').length;if(campaign.runeSequence.length===count){campaign.limiarPuzzle=true;levelRebuildSolids();popup('COBRE → PRATA → OURO · O CAMINHO DO LIMIAR ESTÁ ABERTO');}else popup(rune.label+' · RESSONÂNCIA '+campaign.runeSequence.length+' / '+count);saveCampaign();}
function levelCollectField(item){if(!item||item.done)return false;const it=R.data.items[item.itemId]||R.resolveItem(item.name||(item.kind==='fruit'?'Fruta Roxa':'Pó de Transmutação'),item.icon||''),quantity=item.quantity||1,result=R.addItem(it.id,quantity);if(!result.added){popup('INVENTÁRIO CHEIO · O ITEM CONTINUA NO CHÃO');return false;}item.quantity=result.remaining;if(!result.remaining){item.done=true;campaign.fieldItems=campaign.fieldItems||[];if(item.persistent!==false&&!campaign.fieldItems.includes(item.id))campaign.fieldItems.push(item.id);if(item.respawn?.mode==='timed'){save.rpg.pickupStates[current+':'+item.id]={due:R.now()+item.respawn.delay,mode:'timed'};}else if(item.respawn?.mode==='region')save.rpg.pickupStates[current+':'+item.id]={mode:'region',away:false};}window.CHEMSCAPE_EXPEDITION.event('collect',it.id,result.added,{map:current});if(item.lootKey){const stored=campaign.lootDrops?.[current]?.find(p=>p.id===item.id);if(stored){stored.quantity=item.quantity;stored.done=item.done;}}saveCampaign();popup(it.name+' +'+result.added+(result.remaining?' · '+result.remaining+' NO CHÃO':''));return true;}
function levelInteract(){const target=levelNearby();if(!target)return false;if(target.kind==='experiment'){window.CHEMSCAPE_EXPEDITION.scan(target.token);return true;}if(target.kind==='connection')return levelTraverse(target);if(target.kind==='harvest'){if(addItem(target.harvest.name,target.harvest.icon)){campaign.fieldItems=campaign.fieldItems||[];campaign.fieldItems.push('harvest:'+target.id);saveCampaign();}return true;}if(target.kind==='field'){levelCollectField(pickups.find(p=>p.id===target.id));return true;}if(target.kind==='rune'){levelRune(target);return true;}if(target.kind==='npc'){expOpenDialog(expNpcs.find(n=>n.id===target.id));return true;}if(target.kind==='lab'){returnLab();return true;}if(target.kind==='crystal'){activateCrystal(pickups.find(p=>p.kind==='crystal'&&!p.done));return true;}if(target.kind==='door'){if(LEVELS.rooms?.[target.enter]){saveCampaign();transitionTo(target.enter);}return true;}if(target.kind==='exit'){saveCampaign();transitionTo(activeLevel.parent,null,activeLevel.parentSpawn);return true;}if(target.kind==='portal'){const destination=activeLevel.world==='alchemy'?'world1':'alchemy';saveCampaign();transitionTo(destination,()=>popup(destination==='world1'?'RETORNO AO COMPLEXO AION':'RETORNO A VITRÁLIA'),LEVELS.worlds[destination].returnSpawn||LEVELS.worlds[destination].spawn);return true;}if(target.kind==='sample'){if(!addItem(target.name,target.icon||''))return true;const instance=expSamples.find(v=>v.id===target.id);if(instance)instance.done=true;const key=target.id.startsWith('sample')?'samples':'anchors';campaign[key]=campaign[key]||[];if(!campaign[key].includes(target.id))campaign[key].push(target.id);if(campaign[key].length>=3)campaign[key==='samples'?'samplesCollected':'anchorsCollected']=true;saveCampaign();refreshQuest();refreshJournal();popup(target.name+' · COLETADO');return true;}return false;}
function levelTraverse(target,automatic=false){
 const c=target.connection,maps={...LEVELS.worlds,...LEVELS.rooms},destination=maps[c.target];if(!destination||automatic&&portalCooldown>0||loadingState)return false;if(!editorTesting&&c.requiresFlag&&!campaign[c.requiresFlag]){popup('ACESSO EM ANÁLISE · AVANCE NA INVESTIGAÇÃO INICIAL');return false;}
 if(!editorTesting&&player.level<(c.minLevel||destination.minLevel||1)){popup('REQUER NÍVEL '+(c.minLevel||destination.minLevel));return false;}const spawn=c.spawn||destination.spawn;
 campaign.unlockedMaps=[...new Set([...(campaign.unlockedMaps||[]),c.target])];saveCampaign();transitionTo(c.target,null,spawn);return true;
}
function levelWaypoint(){const el=$('waypoint');if(!player||screen!=='playing'){el.classList.add('hidden');return;}let target,name;const expedition=window.CHEMSCAPE_EXPEDITION.waypoint();if(expedition?.handled){target=expedition.target;name=expedition.name;}else if(activeLevel.parent){target=activeLevel.exit;name='Saída';}else if(current==='world1'&&!campaign.crystalFound){target=campaign.slimeDefeated?activeLevel.crystal:activeLevel.slime;name=campaign.slimeDefeated?'Cristal de Limiar':'Criatura anômala';}else if(current==='alchemy'){let id=!campaign.ilyanaSpoken?'ilyana':!campaign.rukkSpoken?'rukk':campaign.samplesCollected&&!campaign.maeraSpoken||campaign.anchorsCollected&&!campaign.chapter3Complete?'maera':null;if(id){const n=expNpcs.find(n=>n.id===id);if(n){target=[n.x,n.y];name=n.name;}}else if(!campaign.samplesCollected){const sample=expSamples.find(s=>!s.done);if(sample){target=[sample.x,sample.y];name=sample.name;}}else if(!campaign.anchorsCollected){target=activeLevel.portal;name='Portal para o AION';}}else if(current==='world1'&&campaign.maeraSpoken&&!campaign.anchorsCollected){const sample=expSamples.find(s=>!s.done);if(sample){target=[sample.x,sample.y];name=sample.name;}}else if(current==='world1'&&campaign.maeraSpoken){target=activeLevel.portal;name='Portal de Vitrália';}if(!target){el.classList.add('hidden');return;}const dx=target[0]-player.x,dy=target[1]-player.y,d=Math.hypot(dx,dy),dirs=['→','↘','↓','↙','←','↖','↑','↗'];el.textContent=dirs[Math.round(Math.atan2(dy,dx)/(Math.PI/4)+8)%8]+'  '+name+'  ·  '+(d<110?'F PARA INTERAGIR':Math.round(d/32)+' m');el.classList.remove('hidden');}
function levelNpcUpdate(n,dt){n.animClock+=dt;if(n.activity==='training'&&Math.hypot(player.x-n.x,player.y-n.y)>110&&(n.animClock+(n.phase||0))%7<1.5){n.state='attack';n.attack=.1;return;}n.attack=0;n.state=n.activity==='work'?'work':'idle';if(n.activity==='idle'||!n.path?.length||Math.hypot(player.x-n.x,player.y-n.y)<110)return;if(n.waitT>0){n.waitT-=dt;return;}const target=n.path[n.pathIndex],dx=target[0]-n.x,dy=target[1]-n.y,d=Math.hypot(dx,dy);if(d<8){n.pathIndex=(n.pathIndex+1)%n.path.length;n.waitT=1.7;return;}const ox=n.x,oy=n.y;levelMove(n,dx/d*(n.speed??36)*dt,dy/d*(n.speed??36)*dt,10);n.face=dx<0?-1:dx>0?1:n.face;n.state=Math.hypot(n.x-ox,n.y-oy)>.1?'run':'idle';if(n.state==='idle'){n.pathIndex=(n.pathIndex+1)%n.path.length;n.waitT=.8;}}
function levelEnemyUpdate(e,dt){rpgEnemyUpdate(e,dt);}
